import { spawn } from "node:child_process";

// Agents can think for minutes; cap wall-clock. 10m: a repo-grounded run showed
// 5m is too tight for larger evidence-gathering turns.
export const DEFAULT_TIMEOUT_MS = 10 * 60 * 1000;
const TERMINATION_GRACE_MS = 250;

export type CliCapture = { code: number | null; stdout: string; stderr: string; timedOut: boolean };

// Spawn a CLI in `cwd`. stdin is IGNORED (= </dev/null): the canary showed Codex
// hangs waiting for stdin EOF otherwise. stdout/stderr captured separately.
function runCli(cmd: string, args: string[], cwd: string, timeoutMs: number): Promise<CliCapture> {
  return new Promise((resolve) => {
    // On POSIX, detached creates a new process group whose ID is the child's
    // PID. Only signal that group, never the orchestrator's inherited group.
    const useProcessGroup = process.platform !== "win32";
    const child = spawn(cmd, args, { cwd, detached: useProcessGroup, stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    let timedOut = false;
    let settled = false;
    let forceTimer: ReturnType<typeof setTimeout> | undefined;
    const finish = (code: number | null) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      clearTimeout(forceTimer);
      resolve({ code, stdout, stderr, timedOut });
    };
    const signal = (name: NodeJS.Signals) => {
      if (!child.pid) return; // A failed spawn has no process group.
      try {
        if (useProcessGroup) process.kill(-child.pid, name);
        else child.kill(name);
      } catch (e: any) {
        // The group may already have exited. Other failures belong in the
        // capture, but must not prevent the timeout from completing.
        if (e.code !== "ESRCH") stderr += `\n${String(e)}`;
      }
    };
    const timer = setTimeout(() => {
      timedOut = true;
      signal("SIGTERM");
      forceTimer = setTimeout(() => {
        // Run even if the direct child closed: workers may still be alive
        // without holding our pipes open, or may ignore SIGTERM entirely.
        signal("SIGKILL");
        child.stdout.destroy();
        child.stderr.destroy();
        child.unref();
        finish(child.exitCode);
      }, TERMINATION_GRACE_MS);
    }, timeoutMs);
    child.stdout.on("data", (d) => { stdout += d.toString(); });
    child.stderr.on("data", (d) => { stderr += d.toString(); });
    child.on("error", (e) => {
      stderr = String(e);
      if (!timedOut) finish(null);
    });
    child.on("close", (code) => { if (!timedOut) finish(code); });
  });
}

